import json,hashlib
from pathlib import Path
from datetime import datetime,timezone
from fractions import Fraction
p=Path('docs/implementation/PHASE_03_TEMPORAL_PILOT_EVIDENCE.json');e=json.loads(p.read_text());w=Path(e['roots']['worker']);reviews=[];diagnostics=[]
def read(p):return json.loads(p.read_text())
def artifact(p):return {'path':str(p),'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'bytes':p.stat().st_size}
for i in range(8):
 entry=read(w/f'window_{i:03}.json');v={'market_id':entry['item']['member']['market_id'],'question':entry['item']['identity']['question'],'missing_reason':entry['missing_reason'],'sources':[]}
 for rp in sorted((w/f'fs2_capture_screen_{i:03}').glob('*/receipt.json')):
  r=read(rp);raw=rp.parent/'raw.bin';b=raw.read_bytes();j=json.loads(b);j=j[0] if isinstance(j,list) else j
  rec={**artifact(raw),'source_id':r['source_id'],'receipt':artifact(rp),'status':r['status']}
  if r['source_id']=='gamma.market':rec['fields']={k:j.get(k) for k in ['question','description','resolutionSource','active','closed','archived','acceptingOrders','endDate','events']}
  if r['source_id']=='clob.book':
   rec['fields']={'bid_levels':len(j.get('bids',[])) if 'bids' in j else None,'ask_levels':len(j.get('asks',[])) if 'asks' in j else None,'raw_timestamp':j.get('timestamp'),'error':j.get('error')}
   bids=[r for r in j.get('bids',[]) if Fraction(r['size'])>0];asks=[r for r in j.get('asks',[]) if Fraction(r['size'])>0]
   d={'market_id':v['market_id'],'raw_artifact':artifact(raw),'state':next(s['state'] for s in e['screening_states'] if s['market_id']==v['market_id'])}
   if bids and asks:
    bestb=max(Fraction(r['price']) for r in bids);besta=min(Fraction(r['price']) for r in asks)
    bsize=sum(Fraction(r['size']) for r in bids if Fraction(r['price'])==bestb);asize=sum(Fraction(r['size']) for r in asks if Fraction(r['price'])==besta)
    f=(bsize-asize)/(bsize+asize)
    d.update(best_bid=str(bestb),best_ask=str(besta),bid_size=str(bsize),ask_size=str(asize),imbalance=str(f),threshold='1/3',raw_recomputed_trigger=abs(f)>=Fraction(1,3))
    assert d['raw_recomputed_trigger']==(d['state']=='triggered')
   else:d['missingness']='one_sided_or_missing';assert d['state']=='unavailable'
   diagnostics.append(d)
  v['sources'].append(rec)
 v['family_review']={'external':'unavailable_no_pre_origin_rule_matched_source','nws_knyc':'not_applicable_to_quantity_in_rules','related_price':'unavailable_no_pre_origin_group_and_price_binding'}
 reviews.append(v)
e['availability_and_rule_review']=reviews
e['family_eligibility_review']={
 'external':'All8retained rules reviewed in full. Two House districts resolve via reporting/FEC; AAPL/TSLA use specific Pyth candle definitions/corporate-action rules; sports use game/period/statistic-specific rules. None concerns KNYC weather. No relevant external source was admitted/bound before origins. Rule references are not access rights or numerical observations.',
 'related':'CO-02 and TX-04 are distinct districts, not complementary outcomes of one seat. AAPL month-end close and TSLA intramonth low have different instruments/targets. Four sports questions concern distinct games/periods/players. Shared sector/sport/election date is not a verified economic group or complete outcome set; no pre-origin related-price binding exists.',
 'flow_depth_persistence':'F01/F02/F10/F27 remain unavailable. Bounded taker records and partial receipt holds do not prove complete fills, pre-trade ordering, execution-adjusted withdrawal or native continuity.',
 'v1':'Absent v1 seven-component vector and rolling z-score cannot be reconstructed. No v1 predictive result; baseline locking is Phase4.'}
e['control_availability_diagnostic']={'raw_recomputed_assessments':diagnostics,'assessable':6,'triggered':6,'untriggered':0,'unavailable':2,'unfilled_control_slots':6,'interpretation':'No observed untriggered candidate exists anywhere in this frozen sample. Cross-stratum matching alone cannot repair it; unavailable is not negative. Do not change the threshold, infer population prevalence from6cases or redraw merely to pass.'}
e['reviewed_at']=datetime.now(timezone.utc).isoformat()
e['conclusion']='Six-of-eight origin/history and6/6target gates pass; original audit, observer accounting and temporal-population audit pass. Matched-control gate FAILS:6triggered,0untriggered,2unavailable;6unfilled control slots. Phase3 incomplete. No repeated draw or retrospective repair.'
all_artifacts=e['artifacts']+[a for o in e['origins'] for a in o['artifacts']]+[a for v in e['windows'] for a in v['artifacts']]+[a for t in e['target_details'] for a in t['artifacts']]
for a in all_artifacts:
 assert artifact(Path(a['path']))==a
for r in reviews:
 for a in r['sources']:
  assert artifact(Path(a['path']))=={k:a[k] for k in ['path','sha256','bytes']}
  assert artifact(Path(a['receipt']['path']))==a['receipt']
e['independent_artifact_check_count']=len(all_artifacts)
e['preservation_script']={'sha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),'source':Path(__file__).read_text()}
p.write_text(json.dumps(e,indent=2,sort_keys=True)+'\n')
print(json.dumps({'gates':e['execution_gates'],'diagnostic':e['control_availability_diagnostic'],'checked_artifacts':len(all_artifacts),'origin_timing':e['origin_timing']},indent=2))
